<?php require_once __DIR__.'/functions.php'; require_once __DIR__.'/app_init.php'; require_login();$pdo=dogvive_db();$uid=dogvive_user_id();
if($_SERVER['REQUEST_METHOD']==='POST'){try{$rid=(int)($_POST['id_reserva']??0);$method=trim((string)($_POST['metodo']??''));if(!in_array($method,['PSE','Transferencia','Efectivo'],true))throw new RuntimeException('Selecciona un método válido.');$q=$pdo->prepare("SELECT r.id_reserva,r.id_servicio,s.Precio FROM reserva r JOIN servicio s ON s.id_servicio=r.id_servicio WHERE r.id_reserva=? AND r.id_usuario=? AND r.Estado IN ('Confirmada','Completada')");$q->execute([$rid,$uid]);$r=$q->fetch();if(!$r)throw new RuntimeException('Solo puedes registrar el pago de una reserva confirmada o completada.');$existing=$pdo->prepare('SELECT id_pago FROM pago WHERE id_reserva=? AND Estado="Pagado"');$existing->execute([$rid]);if($existing->fetch())throw new RuntimeException('Esta reserva ya aparece como pagada.');$ins=$pdo->prepare('INSERT INTO pago (Valor,Metodo,Fecha,Estado,id_reserva) VALUES (?,?,CURDATE(),?,?)');$ins->execute([(float)$r['Precio'],$method,'Pendiente de verificación',$rid]);dogvive_notice($pdo,$uid,'Pago','Registramos tu intención de pago para la reserva #'.$rid.'. El pago aún no está confirmado.');dogvive_flash('success','Solicitud de pago registrada. Esta versión no procesa cobros reales; el pago queda pendiente de verificación.');header('Location: '.base_url().'/pago.php');exit;}catch(Throwable $e){dogvive_flash('error',$e instanceof RuntimeException?$e->getMessage():'No se pudo registrar el pago.');header('Location: '.base_url().'/pago.php');exit;}}
$q=$pdo->prepare("SELECT r.id_reserva,r.Fecha,r.Estado,s.Nombre AS servicio,s.Precio FROM reserva r JOIN servicio s ON s.id_servicio=r.id_servicio WHERE r.id_usuario=? AND r.Estado IN ('Confirmada','Completada') ORDER BY r.Fecha DESC");$q->execute([$uid]);$rows=$q->fetchAll();$success=dogvive_flash('success');$error=dogvive_flash('error');start_app('Pagos','pago');page_wrap_start('Pagos','Registra una solicitud de pago para una reserva.');if($success)echo '<div class="notice">'.e($success).'</div>';if($error)echo '<div class="error-box">'.e($error).'</div>'; ?>
<div class="card"><div class="notice">Por seguridad, esta página no solicita números de tarjeta ni códigos CVV y no realiza cobros reales. El registro de pago queda pendiente de verificación.</div><?php if(!$rows): ?><p>No tienes reservas confirmadas o completadas pendientes de pago.</p><?= btn('Ver mis reservas',page_url('reservas'),'btn-secondary') ?><?php else: foreach($rows as $r): ?><div class="booking-item"><div class="grow"><strong><?= e($r['servicio']) ?> · Reserva #<?= (int)$r['id_reserva'] ?></strong><small class="muted"><?= e($r['Fecha']) ?> · <?= e($r['Estado']) ?></small><strong>$<?= number_format((float)$r['Precio'],0,',','.') ?> COP</strong></div><form method="post"><input type="hidden" name="id_reserva" value="<?= (int)$r['id_reserva'] ?>"><label>Método<select name="metodo"><option>PSE</option><option>Transferencia</option><option>Efectivo</option></select></label><button class="btn btn-primary" type="submit">Registrar pago</button></form></div><?php endforeach; endif; ?></div><?php page_wrap_end();end_app();
